const crypto = require('crypto');

const secret = $env.N8N_HMAC_SECRET;
const signature = $input.first().headers['x-signature'];
const timestamp = $input.first().headers['x-timestamp'];
const body = JSON.stringify($input.first().body);

// Replay protection: reject if older than 5 minutes
const age = Math.abs(Date.now() - parseInt(timestamp, 10));
if (age > 5 * 60 * 1000) {
  throw new Error('Request expired (replay protection)');
}

const data = `${timestamp}.${body}`;
const expected = crypto.createHmac('sha256', secret).update(data).digest('hex');

const sigBuf = Buffer.from(signature, 'hex');
const expectedBuf = Buffer.from(expected, 'hex');

if (sigBuf.length !== expectedBuf.length || !crypto.timingSafeEqual(sigBuf, expectedBuf)) {
  throw new Error('Invalid HMAC signature');
}

return [{ json: { ...($input.first().body), verified: true } }];

const event = $input.first().json.event;
const requestId = $input.first().json.requestId;
const toolId = $input.first().json.toolId;

let subject, message;

switch (event) {
  case 'borrow_request_created':
    subject = 'New Borrow Request';
    message = `A new borrow request (${requestId}) was created for tool ${toolId}.`;
    break;
  case 'borrow_request_approved':
    subject = 'Borrow Request Approved';
    message = `Borrow request ${requestId} has been approved.`;
    break;
  case 'borrow_request_declined':
    subject = 'Borrow Request Declined';
    message = `Borrow request ${requestId} has been declined.`;
    break;
  case 'loan_started':
    subject = 'Loan Started';
    message = `The tool for request ${requestId} has been picked up.`;
    break;
  case 'loan_returned':
    subject = 'Tool Returned';
    message = `The tool for request ${requestId} has been returned.`;
    break;
  default:
    subject = `LendLoop Event: ${event}`;
    message = `Event ${event} for request ${requestId}.`;
}

return [{ json: { subject, message, event, requestId, toolId, timestamp: new Date().toISOString() } }];

const event = $input.first().json.event;
const requestId = $input.first().json.requestId;

return [{ json: { subject: `LendLoop: ${event}`, message: `Status change event '${event}' for request ${requestId}.`, event, requestId, timestamp: new Date().toISOString() } }];

// Mock notification logger — replace with email/Slack/Discord node in production
const data = $input.first().json;
console.log(`[LendLoop Notification] ${data.subject}: ${data.message}`);
return [{ json: { ...data, notified: true, notifiedAt: new Date().toISOString(), channel: 'mock_log' } }];
